// shortcut: .mjs not .ts because Node 22.13 can't load oxlint.config.ts; switch to .ts on Node >= 22.18.
import cloudflare from '@cloudflare/oxlint-config';
import { defineConfig } from 'oxlint';

export default defineConfig({
  extends: [cloudflare],
  env: cloudflare.env,
  // schema.ts is generated by openapi-typescript (npm run generate -w @push/contracts).
  ignorePatterns: [...cloudflare.ignorePatterns, 'graphify-out/**', 'packages/contracts/src/schema.ts'],
  overrides: [
    {
      // Override, not root rules: preset overrides win over root rules.
      // Error.isError needs Node 24; instanceof is the only error/class check on Node 22.
      files: ['**/*'],
      rules: { '@nkzw/no-instanceof': 'off' },
    },
    {
      // Server code logs through console.error/warn/info; console.log stays banned there.
      files: ['services/*/src/**'],
      rules: { 'no-console': ['error', { allow: ['error', 'warn', 'info'] }] },
    },
    {
      // CLI scripts and tests write to the console on purpose.
      files: ['scripts/**', 'packages/contracts/scripts/**', '**/test/**'],
      rules: { 'no-console': 'off' },
    },
    {
      files: ['**/test/**'],
      rules: {
        // node:test handles the promise a top-level test() or describe() returns.
        'typescript/no-floating-promises': [
          'error',
          { allowForKnownSafeCalls: [{ from: 'package', package: 'node:test', name: ['test', 'it', 'describe', 'suite'] }] },
        ],
      },
    },
  ],
});
